"""TCP transport mechanisms, failure modes, and explicitly scoped congestion controllers."""

WORLD = "net-transport-tcp-v0"
PREFIX = "tcp"
DOMAIN = "networking"
SUBJECT = "networking.transport"
SOURCES = ["rfc9293", "rfc5681", "rfc6298", "rfc2018", "rfc6675", "rfc7323", "rfc6928", "rfc9438", "bbr-2016-queue"]
SCOPE = "TCP as specified by RFC 9293, with RFC 5681 Reno, RFC 6298 timers, RFC 2018/6675 SACK, RFC 7323 scaling, RFC 6928 experimental initial windows, RFC 9438 CUBIC, and the original 2016 BBR paper; later BBR versions, QUIC, application framing, and operating-system-specific tuning are outside scope."
ROOT_LABEL = "TCP transport causation world"
ROOT_STATEMENT = "Root of the TCP transport causation world: how connection state, acknowledgment feedback, receiver capacity, loss recovery, and explicitly identified congestion controllers govern byte delivery and latency."
LIMITATIONS = [
    "Original structured technical summaries; cited documents remain authoritative for complete algorithms and normative requirements.",
    "Protocol behaviors are scoped in each relation; recommendations are described only when the stated implementation follows them.",
    "Numerical examples are constructed cases, not measurements of deployed networks; no universal throughput or fairness guarantee is inferred.",
    "BBR means the model and mechanisms in Cardwell et al., ACM Queue 2016, not later BBR revisions or every implementation called BBR.",
]

