EXAMPLES = [
    ("ordinary-open", "Two different establishment events", "In an ordinary no-data handshake, client SYN uses sequence 100 and server SYN-ACK uses sequence 900 with ACK 101; the client enters ESTABLISHED and sends ACK 901, while the server enters ESTABLISHED only after accepting that final ACK.", ["syn-segment", "syn-ack", "handshake-ack", "established", "sequence-number"]),
    ("gap-with-sack", "A hole blocks later request bytes", "A receiver expecting byte 1000 gets bytes 2000 through 2999 first. Its cumulative ACK stays 1000 and a permitted SACK can report [2000,3000); a read needing those later bytes waits until bytes 1000 through 1999 arrive.", ["receive-gap", "sack-blocks", "cumulative-ack", "head-of-line"]),
    ("credit-minimum", "Receiver tuning cannot bypass cwnd", "A sender has cwnd=12000 bytes, rwnd=64000 bytes, and FlightSize=10000 bytes outside recovery. Its new-data credit is 2000 bytes; raising rwnd to 128000 bytes leaves the same binding congestion limit.", ["congestion-window", "receive-window", "flight-size", "send-allowance"]),
    ("rto-update-order", "RTT deviation uses the old mean", "For an RFC 6298 later sample R=2 seconds, old SRTT=1 second, RTTVAR=0.2 seconds, and G=0.01 seconds, the recommended update gives RTTVAR=0.4 seconds before SRTT=1.125 seconds; the resulting base RTO is 2.725 seconds.", ["rtt-sample", "srtt", "rttvar", "rto"]),
    ("karn-ambiguity", "An ACK cannot date two untagged copies", "Data leaves at time 0, is retransmitted at time 1 second, and is ACKed at time 1.2 seconds without TCP timestamps. The ACK alone cannot choose a 1.2-second or 0.2-second RTT sample, so Karn filtering excludes that measurement.", ["retransmission", "karn-filter", "rtt-sample", "timestamp-echo"]),
    ("reordering-fast-retry", "Intact data can still be retransmitted", "Segment A is delayed while B, C, and D arrive and generate three qualifying duplicate ACKs before A arrives. An RFC 5681 Reno sender retransmits A despite the original eventually arriving intact; the duplicate ACK threshold was an inference, not proof of loss.", ["reordering", "duplicate-ack", "fast-retransmit", "spurious-retransmission"]),
    ("split-request", "A split short request waits for feedback", "An application sends a short request prefix and then a short suffix while the prefix is unacknowledged. With classic Nagle enabled and both pieces below MSS, a peer delaying its ACK can leave the suffix waiting; the server cannot respond until the suffix arrives.", ["small-write", "nagle", "delayed-ack", "nagle-delay", "request-completion"]),
    ("scale-direction", "Decode the peer's scale on later ACKs", "Both peers exchange RFC 7323 scale options; the server offers shift 7. Its SYN-ACK window field 4000 still means 4000 bytes, but a later non-SYN window field 4000 from that server means 512000 bytes of receive credit, independently of the client's offered shift.", ["scale-exchange", "scale-shift", "encoded-window", "receive-window"]),
    ("lost-reopen", "Probe repairs a lost reopening update", "A receiver advertises zero credit, then the application consumes data and the reopening ACK is lost. A later zero-window probe elicits a fresh current-window ACK; once that reaches the sender, available congestion credit can again permit queued new bytes.", ["zero-window", "application-read", "zero-window-probe", "window-update", "new-transmission"]),
    ("close-ack-loss", "A retained closer can repeat the last ACK", "Client A has sent and received acknowledgment of its FIN, then accepts server B's FIN and enters TIME-WAIT. A's closing ACK is lost; B repeats its FIN, and A acknowledges it again and restarts the ordinary two-MSL wait.", ["fin", "time-wait", "fin-retransmission", "final-ack"]),
    ("bottleneck-wait", "A queue adds delay without adding path capacity", "In a constructed FIFO fluid bottleneck serving 1000000 bytes per second, 200000 bytes ahead add 0.2 seconds of queueing. If sustained TCP offered load maintains that backlog in a deep drop-tail queue, more buffer capacity does not raise the bottleneck service rate.", ["bottleneck-rate", "queue", "queue-delay", "deep-buffer", "bufferbloat"]),
    ("sack-reneging-retention-case", "Keep bytes until cumulative acknowledgment", "A sender has ACK 1000 and SACK [2000,3000). The receiver later discards that out-of-order block under memory pressure. Keeping bytes 2000 through 2999 until a cumulative ACK covers them lets the sender repair the reneged range when recovery requests it.", ["sack-blocks", "sack-reneging", "sender-retention", "retransmission"]),
    ("cubic-loss-calculation", "CUBIC uses flight size in its loss response", "With RFC 9438 beta_cubic=0.7, flight_size=100 segments, and cwnd=120 segments, a packet-loss event sets the specified reduction value to 70 segments, above the two-segment floor; blindly halving cwnd to 60 segments implements a different rule.", ["cubic-beta", "cubic-reduction", "congestion-window", "flight-size", "ssthresh"]),
    ("bbr-model", "Original BBR estimates and probing are conditional", "In a constructed 2016 BBR model with BtlBw=1000000 bytes per second and RTprop=0.05 seconds, the estimated propagation BDP is 50000 bytes; a pacing gain above one probes beyond the estimate and can build a queue if no extra bottleneck service is available.", ["bbr-bandwidth", "bbr-min-rtt", "bdp", "bbr-pacing", "bbr-probebw"]),
]

